before:
Complete local C++ example; the app itself does not execute it:
```cpp
#include <functional>
#include <iostream>
int main() {
    std::function<int(int)> operation = [](int x) { return x + 1; };
    std::cout << operation(3) << '\n';
    operation = [](int x) { return x * 2; };
    if (operation) std::cout << operation(3) << '\n';
}

```

